import { z } from "zod";
import {
  DateTimeSchema,
  RefSchema,
  SlugSchema,
  TaskStatusSchema,
  TaskTypeSchema,
  UlidSchema,
  VcsRefSchema,
} from "./common.js";

/**
 * Automation eligibility status for tasks
 * AC: @task-automation-eligibility ac-1
 * - eligible: Task can be processed by automation loops
 * - needs_review: Task was rejected by automation and needs human review
 * - manual_only: Task should only be handled by humans
 * - undefined/absent: Task has not been assessed for automation (unassessed)
 */
export const AutomationStatusSchema = z.enum([
  "eligible",
  "needs_review",
  "manual_only",
]);

/**
 * Note entry - append-only work log
 */
export const NoteSchema = z.object({
  _ulid: UlidSchema,
  created_at: DateTimeSchema,
  author: z.string().optional(),
  content: z.string(),
  supersedes: UlidSchema.nullable().optional(),
});

/**
 * Todo item - lightweight checklist
 */
export const TodoSchema = z.object({
  id: z.number().int().positive(),
  text: z.string(),
  done: z.boolean().default(false),
  done_at: DateTimeSchema.optional(),
  added_at: DateTimeSchema,
  added_by: z.string().optional(),
  promoted_to: RefSchema.optional(),
});

/**
 * Full task schema
 * Note: created_at defaults to now if not provided (auto-populated on load)
 */
export const TaskSchema = z.object({
  // Identity
  _ulid: UlidSchema,
  slugs: z.array(SlugSchema).default([]),
  title: z.string().min(1, "Title is required"),
  type: TaskTypeSchema.default("task"),

  // Content (doesn't duplicate spec - brief description for standalone context)
  description: z.string().optional(),

  // Spec relationship
  spec_ref: RefSchema.nullable().optional(),
  derivation: z.enum(["auto", "manual"]).optional(),

  // Meta relationship (links to workflow, agent, or convention for process improvement tracking)
  meta_ref: RefSchema.nullable().optional(),

  // Plan relationship (links to the plan this task was derived from)
  // AC: @plan-derive ac-5, ac-6
  plan_ref: RefSchema.nullable().optional(),

  // Origin tracking (where this task came from)
  origin: z.enum(["manual", "derived", "observation_promotion"]).optional(),

  // State
  status: TaskStatusSchema.default("pending"),
  blocked_by: z.array(z.string()).default([]),
  closed_reason: z.string().nullable().optional(),

  // Dependencies
  depends_on: z.array(RefSchema).default([]),
  context: z.array(RefSchema).default([]),

  // Work metadata
  priority: z.number().int().min(1).max(5).default(3),
  complexity: z.number().int().min(1).max(5).optional(),
  tags: z.array(z.string()).default([]),
  assignee: z.string().nullable().optional(),

  // VCS references
  vcs_refs: z.array(VcsRefSchema).default([]),

  // Review URL (PR, MR, or external review link — set at submit time)
  // AC: @task-submit ac-submit-2
  review_url: z.string().url().optional(),

  // Session scoping (advisory, not enforced)
  // AC: @session-scoped-task-claiming ac-schema
  session_id: z.string().nullable().optional(),

  // Timestamps (auto-populated if not provided)
  created_at: DateTimeSchema.default(() => new Date().toISOString()),
  started_at: DateTimeSchema.nullable().optional(),
  submitted_at: DateTimeSchema.nullable().optional(),
  completed_at: DateTimeSchema.nullable().optional(),

  // Notes (work log)
  notes: z.array(NoteSchema).default([]),

  // Todos (emergent subtasks)
  todos: z.array(TodoSchema).default([]),

  // Automation eligibility (AC: @task-automation-eligibility ac-1, ac-2)
  // Optional - absent means unassessed
  automation: AutomationStatusSchema.optional(),
});

/**
 * Task input schema (for creating new tasks, some fields auto-generated)
 * All fields except title are optional - defaults will be applied
 */
export const TaskInputSchema = z.object({
  // Identity (auto-generated if not provided)
  _ulid: UlidSchema.optional(),
  slugs: z.array(SlugSchema).optional(),
  title: z.string().min(1, "Title is required"),
  type: TaskTypeSchema.optional(),

  // Content
  description: z.string().optional(),

  // Spec relationship
  spec_ref: RefSchema.nullable().optional(),
  derivation: z.enum(["auto", "manual"]).optional(),

  // Meta relationship
  meta_ref: RefSchema.nullable().optional(),

  // Plan relationship
  plan_ref: RefSchema.nullable().optional(),

  // Origin tracking
  origin: z.enum(["manual", "derived", "observation_promotion"]).optional(),

  // State
  status: TaskStatusSchema.optional(),
  blocked_by: z.array(z.string()).optional(),
  closed_reason: z.string().nullable().optional(),

  // Dependencies
  depends_on: z.array(RefSchema).optional(),
  context: z.array(RefSchema).optional(),

  // Work metadata
  priority: z.number().int().min(1).max(5).optional(),
  complexity: z.number().int().min(1).max(5).optional(),
  tags: z.array(z.string()).optional(),
  assignee: z.string().nullable().optional(),

  // VCS references
  vcs_refs: z.array(VcsRefSchema).optional(),

  // Review URL
  review_url: z.string().url().optional(),

  // Session scoping
  session_id: z.string().nullable().optional(),

  // Timestamps
  created_at: DateTimeSchema.optional(),
  started_at: DateTimeSchema.nullable().optional(),
  submitted_at: DateTimeSchema.nullable().optional(),
  completed_at: DateTimeSchema.nullable().optional(),

  // Notes (work log)
  notes: z.array(NoteSchema).optional(),

  // Todos (emergent subtasks)
  todos: z.array(TodoSchema).optional(),

  // Automation eligibility (AC: @task-automation-eligibility ac-1, ac-2, ac-13)
  automation: AutomationStatusSchema.optional(),
});

/**
 * Tasks file schema (collection of tasks)
 */
export const TasksFileSchema = z.object({
  kynetic_tasks: z.string().default("1.0"),
  tasks: z.array(TaskSchema),
});

export type Note = z.infer<typeof NoteSchema>;
export type Todo = z.infer<typeof TodoSchema>;
export type Task = z.infer<typeof TaskSchema>;
export type TaskInput = z.infer<typeof TaskInputSchema>;
export type TasksFile = z.infer<typeof TasksFileSchema>;

// AC: @api-contract ac-2 - Return with status, priority, spec_ref, notes count
// AC: @web-dashboard ac-1 - Include depends_on for blocked task computation
const items = paginated.map((task) => ({
  _ulid: task._ulid,
  slugs: task.slugs,
  title: task.title,
  status: task.status,
  priority: task.priority,
  spec_ref: task.spec_ref,
  meta_ref: task.meta_ref,
  tags: task.tags,
  depends_on: task.depends_on || [],
  notes_count: task.notes?.length || 0,
  todos_count: task.todos?.length || 0,
  started_at: task.started_at,
  completed_at: task.completed_at,
  created_at: task.created_at,
}));

// AC: @api-contract ac-4, @trait-api-endpoint ac-4 - Return pagination wrapper

/**
 * Task API Routes
 *
 * REST endpoints for task operations:
 * - GET /api/tasks - list with filters and pagination
 * - GET /api/tasks/:ref - get single task
 * - POST /api/tasks/:ref/start - start task
 * - POST /api/tasks/:ref/note - add note
 *
 * AC Coverage:
 * - ac-2: GET /api/tasks returns array with status, priority, spec_ref, notes count
 * - ac-3: Status filter with multi-value support
 * - ac-4: Pagination with {items, total, offset, limit} wrapper
 * - ac-5: GET /api/tasks/:ref resolves via ReferenceIndex
 * - ac-6: POST /api/tasks/:ref/start transitions state
 * - ac-7: POST /api/tasks/:ref/note appends note
 */

import { Elysia, t } from 'elysia';
import {
  initContext,
  loadAllTasks,
  loadAllItems,
  ReferenceIndex,
  createNote,
  saveTask,
  getAuthor,
  syncSpecImplementationStatus,
  type LoadedTask,
} from '../../parser/index.js';
import { commitIfShadow } from '../../parser/shadow.js';
import type { PubSubManager } from '../websocket/pubsub';

interface TasksRouteOptions {
  pubsub: PubSubManager;
}

export function createTasksRoutes(options: TasksRouteOptions) {
  const { pubsub } = options;

  return new Elysia({ prefix: '/api/tasks' })
    // AC: @api-contract ac-2, ac-3, ac-4 - List tasks with filters and pagination
    .get(
      '/',
      async ({ query, projectContext }) => {
        // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
        const ctx = await initContext(projectContext.path);
        const tasks = await loadAllTasks(ctx);
        const specItems = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, specItems);

        // Apply filters
        let filtered = tasks;

        // AC: @api-contract ac-3 - Multi-value status filter
        if (query.status) {
          const statusFilters = Array.isArray(query.status) ? query.status : [query.status];
          filtered = filtered.filter((task) => statusFilters.includes(task.status));
        }

        // Type filter (optional, not in ACs but useful)
        if (query.type) {
          const typeFilters = Array.isArray(query.type) ? query.type : [query.type];
          filtered = filtered.filter((task) => task.type && typeFilters.includes(task.type));
        }

        // Tag filter (optional, not in ACs but useful)
        if (query.tag) {
          const tagFilters = Array.isArray(query.tag) ? query.tag : [query.tag];
          filtered = filtered.filter((task) =>
            task.tags?.some((t) => tagFilters.includes(t))
          );
        }

        // AC: @api-contract ac-4 - Pagination
        const total = filtered.length;
        const offset = Number(query.offset) || 0;
        const limit = Number(query.limit) || total;

        const paginated = filtered.slice(offset, offset + limit);

        // AC: @api-contract ac-2 - Return with status, priority, spec_ref, notes count
        // AC: @web-dashboard ac-1 - Include depends_on for blocked task computation
        const items = paginated.map((task) => ({
          _ulid: task._ulid,
          slugs: task.slugs,
          title: task.title,
          status: task.status,
          priority: task.priority,
          spec_ref: task.spec_ref,
          meta_ref: task.meta_ref,
          tags: task.tags,
          depends_on: task.depends_on || [],
          notes_count: task.notes?.length || 0,
          todos_count: task.todos?.length || 0,
          started_at: task.started_at,
          completed_at: task.completed_at,
          created_at: task.created_at,
        }));

        // AC: @api-contract ac-4, @trait-api-endpoint ac-4 - Return pagination wrapper
        return {
          items,
          total,
          offset,
          limit,
        };
      },
      {
        query: t.Object({
          status: t.Optional(t.Union([t.String(), t.Array(t.String())])),
          type: t.Optional(t.Union([t.String(), t.Array(t.String())])),
          tag: t.Optional(t.Union([t.String(), t.Array(t.String())])),
          limit: t.Optional(t.String()),
          offset: t.Optional(t.String()),
        }),
      }
    )

    // AC: @api-contract ac-5 - Get single task by ref
    .get(
      '/:ref',
      async ({ params, error: errorResponse, projectContext }) => {
        // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
        const ctx = await initContext(projectContext.path);
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);

        // AC: @api-contract ac-5, @trait-api-endpoint ac-2 - Resolve ref via ReferenceIndex
        const result = index.resolve(params.ref);

        if (!result.ok) {
          // AC: @trait-api-endpoint ac-2 - Return 404 with error details
          return errorResponse(404, {
            error: 'not_found',
            message: `Task reference "${params.ref}" not found`,
            suggestion: 'Use kspec task list or kspec search to find valid task references',
          });
        }

        // Find the task
        const task = tasks.find((t) => t._ulid === result.ulid);
        if (!task) {
          return errorResponse(404, {
            error: 'not_found',
            message: `Reference "${params.ref}" is not a task`,
            suggestion: 'This reference might point to a spec item instead',
          });
        }

        // AC: @api-contract ac-5 - Return full task with notes, todos, dependencies
        return {
          _ulid: task._ulid,
          slugs: task.slugs,
          title: task.title,
          status: task.status,
          priority: task.priority,
          spec_ref: task.spec_ref,
          meta_ref: task.meta_ref,
          tags: task.tags,
          description: task.description,
          depends_on: task.depends_on,
          notes: task.notes,
          todos: task.todos,
          started_at: task.started_at,
          completed_at: task.completed_at,
          cancelled_at: task.cancelled_at,
          closed_reason: task.closed_reason,
          automation: task.automation,
          created_at: task.created_at,
        };
      },
      {
        params: t.Object({
          ref: t.String(),
        }),
      }
    )

    // AC: @api-contract ac-6 - Start task
    .post(
      '/:ref/start',
      async ({ params, error: errorResponse, projectContext }) => {
        // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
        const ctx = await initContext(projectContext.path);
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);

        // Resolve ref
        const result = index.resolve(params.ref);
        if (!result.ok) {
          return errorResponse(404, {
            error: 'not_found',
            message: `Task reference "${params.ref}" not found`,
            suggestion: 'Use kspec task list to find valid task references',
          });
        }

        const task = tasks.find((t) => t._ulid === result.ulid);
        if (!task) {
          return errorResponse(404, {
            error: 'not_found',
            message: `Reference "${params.ref}" is not a task`,
          });
        }

        // AC: @api-contract ac-6 - Transition to in_progress
        if (task.status === 'in_progress') {
          return errorResponse(409, {
            error: 'invalid_transition',
            message: 'Task is already in_progress',
            current: task.status,
            valid_transitions: ['blocked', 'pending_review', 'completed', 'cancelled'],
          });
        }

        // Update task status
        const updatedTask: LoadedTask = {
          ...task,
          status: 'in_progress',
          started_at: task.started_at || new Date().toISOString(),
        };

        // Save and commit
        await saveTask(ctx, updatedTask);
        await syncSpecImplementationStatus(ctx, updatedTask, tasks, items, index);
        await commitIfShadow(ctx.shadow, `task: start ${params.ref}`);

        // AC: @api-contract ac-6, @trait-api-endpoint ac-5 - WebSocket broadcast
        // AC: @multi-directory-daemon ac-18 - Broadcast scoped to request project
        pubsub.broadcast('tasks:updates', 'task_updated', {
          ref: params.ref,
          ulid: task._ulid,
          action: 'start',
          status: 'in_progress',
        }, projectContext.path);

        // AC: @api-contract ac-6 - Return updated task
        return updatedTask;
      },
      {
        params: t.Object({
          ref: t.String(),
        }),
      }
    )

    // AC: @api-contract ac-7 - Add note to task
    .post(
      '/:ref/note',
      async ({ params, body, error: errorResponse, projectContext }) => {
        // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
        const ctx = await initContext(projectContext.path);
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);

        // Resolve ref
        const result = index.resolve(params.ref);
        if (!result.ok) {
          return errorResponse(404, {
            error: 'not_found',
            message: `Task reference "${params.ref}" not found`,
          });
        }

        const task = tasks.find((t) => t._ulid === result.ulid);
        if (!task) {
          return errorResponse(404, {
            error: 'not_found',
            message: `Reference "${params.ref}" is not a task`,
          });
        }

        // AC: @trait-api-endpoint ac-3 - Validate body
        if (!body.content || typeof body.content !== 'string') {
          return errorResponse(400, {
            error: 'validation_error',
            details: [
              {
                field: 'content',
                message: 'Content is required and must be a string',
              },
            ],
          });
        }

        // AC: @api-contract ac-7 - Append note
        const author = getAuthor(ctx.config?.identity?.author);
        const note = createNote(body.content, author);

        const updatedTask: LoadedTask = {
          ...task,
          notes: [...(task.notes || []), note],
        };

        // AC: @api-contract ac-7, @trait-api-endpoint ac-5 - Shadow commit
        await saveTask(ctx, updatedTask);
        await commitIfShadow(ctx.shadow, `task: add note to ${params.ref}`);

        // AC: @api-contract ac-7 - WebSocket broadcast
        // AC: @multi-directory-daemon ac-18 - Broadcast scoped to request project
        pubsub.broadcast('tasks:updates', 'task_updated', {
          ref: params.ref,
          ulid: task._ulid,
          action: 'note_added',
          note_ulid: note._ulid,
        }, projectContext.path);

        return {
          success: true,
          note,
          task: updatedTask,
        };
      },
      {
        params: t.Object({
          ref: t.String(),
        }),
        body: t.Object({
          content: t.String(),
        }),
      }
    );
}

