    11→ * - ac-9: Type filter with multi-value support
    12→ * - ac-10: GET /api/items/:ref with full details
    13→ * - ac-11: GET /api/items/:ref/tasks via AlignmentIndex
    14→ */
    15→
    16→import { Elysia, t } from 'elysia';
    17→import {
    18→  initContext,
    19→  loadAllItems,
    20→  loadAllTasks,
    21→  ReferenceIndex,
    22→  AlignmentIndex,
    23→  getCachedTestCoverage,
    24→  computeACCoverage,
    25→  type LoadedSpecItem,
    26→} from '../../parser/index.js';
    27→
    28→interface ItemsRouteOptions {}
    29→
    30→/**
    31→ * Compute parent ULIDs for items based on _path and _sourceFile.
    32→ * Items are nested when they share the same source file and
    33→ * one item's path is a prefix of another's path.
    34→ */
    35→function computeParentMap(items: LoadedSpecItem[]): Map<string, string | undefined> {
    36→  const parentMap = new Map<string, string | undefined>();
    37→
    38→  // Group items by source file
    39→  const byFile = new Map<string, LoadedSpecItem[]>();
    40→  for (const item of items) {
    41→    const file = item._sourceFile || '';
    42→    if (!byFile.has(file)) {
    43→      byFile.set(file, []);
    44→    }
    45→    byFile.get(file)!.push(item);
    46→  }
    47→
    48→  // For each file, determine parent relationships based on path
    49→  for (const [, fileItems] of byFile) {
    50→    // Sort by path length (shorter paths are potential parents)
    51→    const sorted = [...fileItems].sort((a, b) => {
    52→      const aLen = a._path?.length || 0;
    53→      const bLen = b._path?.length || 0;
    54→      return aLen - bLen;
    55→    });
    56→
    57→    for (const item of sorted) {
    58→      const itemPath = item._path;
    59→
    60→      if (!itemPath) {
    61→        // Root item in file - no parent
    62→        parentMap.set(item._ulid, undefined);
    63→        continue;
    64→      }
    65→
    66→      // Find the closest parent by matching path prefix
    67→      // Path format: "features[0].requirements[0]"
    68→      // Parent path: "features[0]" or undefined (root item)
    69→      const lastDot = itemPath.lastIndexOf('.');
    70→      const parentPath = lastDot > -1 ? itemPath.substring(0, lastDot) : undefined;
    71→
    72→      // Find parent item
    73→      let parentUlid: string | undefined;
    74→      if (parentPath === undefined) {
    75→        // Direct child of the root item (the item with no path)
    76→        const rootItem = fileItems.find(i => !i._path);
    77→        parentUlid = rootItem?._ulid;
    78→      } else {
    79→        // Find item with matching parent path
    80→        const parentItem = fileItems.find(i => i._path === parentPath);
    81→        parentUlid = parentItem?._ulid;
    82→      }
    83→
    84→      parentMap.set(item._ulid, parentUlid);
    85→    }
    86→  }
    87→
    88→  return parentMap;
    89→}
    90→
    91→export function createItemsRoutes(options: ItemsRouteOptions = {}) {
    92→  // No closure-scoped kspecDir needed - comes from middleware
    93→
    94→  return new Elysia({ prefix: '/api/items' })
    95→    // AC: @api-contract ac-8, ac-9 - List items with type filter
    96→    .get(
    97→      '/',
    98→      async ({ query, projectContext }) => {
    99→        // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
   100→        const ctx = await initContext(projectContext.path);
   101→        const items = await loadAllItems(ctx);
   102→
   103→        // Compute parent relationships from path structure
   104→        const parentMap = computeParentMap(items);
   105→
   106→        // Apply filters
   107→        let filtered = items;
   108→
   109→        // AC: @api-contract ac-9 - Multi-value type filter
   110→        if (query.type) {
   111→          const typeFilters = Array.isArray(query.type) ? query.type : [query.type];
   112→          filtered = filtered.filter((item) => typeFilters.includes(item.type));
   113→        }
   114→
   115→        // Optional maturity filter (not in ACs but useful)
   116→        if (query.maturity) {
   117→          const maturityFilters = Array.isArray(query.maturity) ? query.maturity : [query.maturity];
   118→          filtered = filtered.filter((item) => {
   119→            if (typeof item.status === 'object' && item.status?.maturity) {
   120→              return maturityFilters.includes(item.status.maturity);
   121→            }
   122→            return false;
   123→          });
   124→        }
   125→
   126→        // Optional implementation filter (not in ACs but useful)
   127→        if (query.implementation) {
   128→          const implFilters = Array.isArray(query.implementation)
   129→            ? query.implementation
   130→            : [query.implementation];
   131→          filtered = filtered.filter((item) => {
   132→            if (typeof item.status === 'object' && item.status?.implementation) {
   133→              return implFilters.includes(item.status.implementation);
   134→            }
   135→            return false;
   136→          });
   137→        }
   138→
   139→        // Tag filter (not in ACs but useful)
   140→        if (query.tag) {
   141→          const tagFilters = Array.isArray(query.tag) ? query.tag : [query.tag];
   142→          filtered = filtered.filter((item) =>
   143→            item.tags?.some((t) => tagFilters.includes(t))
   144→          );
   145→        }
   146→
   147→        // Pagination
   148→        const total = filtered.length;
   149→        const offset = Number(query.offset) || 0;
   150→        const limit = Number(query.limit) || total;
   151→
   152→        const paginated = filtered.slice(offset, offset + limit);
   153→
   154→        // AC: @api-contract ac-8 - Return spec items (modules, features, requirements)
   155→        const result = paginated.map((item) => ({
   156→          _ulid: item._ulid,
   157→          slugs: item.slugs,
   158→          title: item.title,
   159→          type: item.type,
   160→          status: item.status,
   161→          tags: item.tags,
   162→          parent: parentMap.get(item._ulid),
   163→          created_at: item.created_at,
   164→          acceptance_criteria_count: item.acceptance_criteria?.length || 0,
   165→        }));
   166→
   167→        // AC: @trait-api-endpoint ac-4 - Return pagination wrapper
   168→        return {
   169→          items: result,
   170→          total,
   171→          offset,
   172→          limit,
   173→        };
   174→      },
   175→      {
   176→        query: t.Object({
   177→          type: t.Optional(t.Union([t.String(), t.Array(t.String())])),
   178→          maturity: t.Optional(t.Union([t.String(), t.Array(t.String())])),
   179→          implementation: t.Optional(t.Union([t.String(), t.Array(t.String())])),
   180→          tag: t.Optional(t.Union([t.String(), t.Array(t.String())])),
   181→          limit: t.Optional(t.String()),
   182→          offset: t.Optional(t.String()),
   183→        }),
   184→      }
   185→    )
   186→
   187→    // AC: @api-contract ac-10 - Get single item by ref
   188→    .get(
   189→      '/:ref',
   190→      async ({ params, error: errorResponse, projectContext }) => {
   191→        // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
   192→        const ctx = await initContext(projectContext.path);
   193→        const items = await loadAllItems(ctx);
   194→        const tasks = await loadAllTasks(ctx);
   195→        const index = new ReferenceIndex(tasks, items);
   196→
   197→        // Compute parent relationships from path structure
   198→        const parentMap = computeParentMap(items);
   199→
   200→        // AC: @api-contract ac-10, @trait-api-endpoint ac-2 - Resolve ref via ReferenceIndex
   201→        const result = index.resolve(params.ref);
   202→
   203→        if (!result.ok) {
   204→          // AC: @trait-api-endpoint ac-2 - Return 404 with error details
   205→          return errorResponse(404, {
   206→            error: 'not_found',
   207→            message: `Item reference "${params.ref}" not found`,
   208→            suggestion: 'Use kspec item list or kspec search to find valid item references',
   209→          });
   210→        }
   211→
   212→        // Find the item
   213→        const item = items.find((i) => i._ulid === result.ulid);
   214→        if (!item) {
   215→          return errorResponse(404, {
   216→            error: 'not_found',
   217→            message: `Reference "${params.ref}" is not a spec item`,
   218→            suggestion: 'This reference might point to a task instead',
   219→          });
   220→        }
   221→
   222→        // AC: @web-dashboard ac-15 - Compute test coverage for acceptance criteria
   223→        // Uses cached coverage scan for performance (avoids re-scanning on every request)
   224→        let acceptanceCriteriaWithCoverage = item.acceptance_criteria;
   225→        if (item.acceptance_criteria && item.acceptance_criteria.length > 0) {
   226→          try {
   227→            const coveredACs = await getCachedTestCoverage(projectContext.path);
   228→            acceptanceCriteriaWithCoverage = computeACCoverage(item, coveredACs);
   229→          } catch (err) {
   230→            // Coverage scan failed - leave as undefined
   231→            console.warn('AC coverage scan failed:', err);
   232→          }
   233→        }
   234→
   235→        // AC: @api-contract ac-10 - Return full item with acceptance_criteria, traits, relationships
   236→        return {
   237→          _ulid: item._ulid,
   238→          slugs: item.slugs,
   239→          title: item.title,
   240→          type: item.type,
   241→          status: item.status,
   242→          tags: item.tags,
   243→          parent: parentMap.get(item._ulid),
   244→          description: item.description,
   245→          acceptance_criteria: acceptanceCriteriaWithCoverage,
   246→          traits: item.traits,
   247→          relationships: item.relationships,
   248→          created_at: item.created_at,
   249→          _sourceFile: item._sourceFile,
   250→        };
   251→      },
   252→      {
   253→        params: t.Object({
   254→          ref: t.String(),
   255→        }),
   256→      }
   257→    )
   258→
   259→    // AC: @api-contract ac-11 - Get tasks linked to spec item
   260→    .get(
   261→      '/:ref/tasks',
   262→      async ({ params, error: errorResponse, projectContext }) => {
   263→        // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
   264→        const ctx = await initContext(projectContext.path);
   265→        const items = await loadAllItems(ctx);
   266→        const tasks = await loadAllTasks(ctx);
   267→        const refIndex = new ReferenceIndex(tasks, items);
   268→        const alignIndex = new AlignmentIndex(tasks, items);
   269→        alignIndex.buildLinks(refIndex);
   270→
   271→        // Resolve ref
   272→        const result = refIndex.resolve(params.ref);
   273→
   274→        if (!result.ok) {
   275→          return errorResponse(404, {
   276→            error: 'not_found',
   277→            message: `Item reference "${params.ref}" not found`,
   278→            suggestion: 'Use kspec item list to find valid item references',
   279→          });
   280→        }
   281→
   282→        const item = items.find((i) => i._ulid === result.ulid);
   283→        if (!item) {
   284→          return errorResponse(404, {
   285→            error: 'not_found',
   286→            message: `Reference "${params.ref}" is not a spec item`,
   287→          });
   288→        }
   289→
   290→        // AC: @api-contract ac-11 - Get tasks via AlignmentIndex
   291→        const linkedTasks = alignIndex.getTasksForSpec(result.ulid);
   292→
   293→        // Return tasks with summary info
   294→        const result_items = linkedTasks.map((task) => ({
   295→          _ulid: task._ulid,
   296→          slugs: task.slugs,
   297→          title: task.title,
   298→          type: task.type || 'task',
   299→          status: task.status,
   300→          priority: task.priority,
   301→          spec_ref: task.spec_ref,
   302→          tags: task.tags || [],
   303→          depends_on: task.depends_on || [],
   304→          started_at: task.started_at,
   305→          completed_at: task.completed_at,
   306→          created_at: task.created_at,
   307→          notes_count: task.notes?.length || 0,
   308→          todos_count: task.todos?.length || 0,
   309→        }));
   310→
   311→        return {
   312→          items: result_items,
   313→          total: result_items.length,
   314→        };
   315→      },
   316→      {
   317→        params: t.Object({
   318→          ref: t.String(),
   319→        }),
   320→      }
   321→    );
   322→}
   323→
