   247→ * AC: @gh-pages-export ac-13
   248→ */
   249→export function fetchItemStatic(ref: string): ItemDetail | null {
   250→	const snapshot = getSnapshot();
   251→	if (!snapshot) return null;
   252→
   253→	const item = findItemByRef(snapshot.items, ref);
   254→	if (!item) return null;
   255→
   256→	return item;
   257→}
   258→
   259→/**
   260→ * Fetch tasks linked to an item from static snapshot
   261→ */
   262→export function fetchItemTasksStatic(ref: string): PaginatedResponse<TaskSummary> {
   263→	const snapshot = getSnapshot();
   264→	if (!snapshot) {
   265→		return { items: [], total: 0, offset: 0, limit: 50 };
   266→	}
   267→
   268→	const item = findItemByRef(snapshot.items, ref);
   269→	if (!item) {
   270→		return { items: [], total: 0, offset: 0, limit: 50 };
   271→	}
   272→
   273→	// Find tasks that reference this item
   274→	const linkedTasks = snapshot.tasks.filter((t) => {
   275→		if (!t.spec_ref) return false;
   276→		const specRef = t.spec_ref.startsWith('@') ? t.spec_ref.slice(1) : t.spec_ref;
   277→		return item.slugs.includes(specRef) || item._ulid.startsWith(specRef.toUpperCase());
   278→	});
   279→
   280→	return {
   281→		items: linkedTasks.map(toTaskSummary),
   282→		total: linkedTasks.length,
   283→		offset: 0,
   284→		limit: linkedTasks.length
   285→	};
   286→}
   287→
   288→/**
   289→ * Fetch inbox from static snapshot
   290→ * AC: @gh-pages-export ac-11
   291→ */
   292→export function fetchInboxStatic(params?: {
   293→	limit?: number;
   294→	offset?: number;
   295→}): PaginatedResponse<InboxItem> {
   296→	const snapshot = getSnapshot();
   297→	if (!snapshot) {
   298→		return { items: [], total: 0, offset: 0, limit: 50 };
   299→	}
   300→
   301→	return paginate(snapshot.inbox, params);
   302→}
   303→
   304→/**
   305→ * Fetch session context from static snapshot
   306→ */
   307→export function fetchSessionContextStatic(): SessionContext | null {
   308→	const snapshot = getSnapshot();
   309→	return snapshot?.session ?? null;
   310→}
   311→
   312→/**
   313→ * Fetch observations from static snapshot
   314→ */
   315→export function fetchObservationsStatic(params?: {
   316→	type?: 'friction' | 'success' | 'question' | 'idea';
   317→	resolved?: boolean;
   318→}): PaginatedResponse<Observation> {
   319→	const snapshot = getSnapshot();
   320→	if (!snapshot) {
   321→		return { items: [], total: 0, offset: 0, limit: 50 };
   322→	}
   323→
   324→	let filtered = snapshot.observations;
   325→
   326→	if (params?.type) {
   327→		filtered = filtered.filter((o) => o.type === params.type);
   328→	}
   329→	if (params?.resolved !== undefined) {
   330→		filtered = filtered.filter((o) => o.resolved === params.resolved);
   331→	}
   332→
   333→	return {
   334→		items: filtered,
   335→		total: filtered.length,
   336→		offset: 0,
   337→		limit: filtered.length
   338→	};
   339→}
   340→
   341→/**
   342→ * Search across static snapshot
   343→ * AC: @gh-pages-export ac-11
   344→ */
   345→export function searchStatic(query: string): SearchResponse {
   346→	const snapshot = getSnapshot();
   347→	if (!snapshot) {
   348→		return { results: [], total: 0, showing: 0 };
   349→	}
   350→
   351→	const lowerQuery = query.toLowerCase();
   352→	const results: SearchResult[] = [];
   353→
   354→	// Search tasks
   355→	for (const task of snapshot.tasks) {
   356→		if (
   357→			task.title.toLowerCase().includes(lowerQuery) ||
   358→			task.slugs.some((s) => s.includes(lowerQuery))
   359→		) {
   360→			results.push({
   361→				type: 'task',
   362→				ulid: task._ulid,
   363→				title: task.title,
   364→				matchedFields: ['title']
   365→			});
   366→		}
   367→	}
   368→
   369→	// Search items
   370→	for (const item of snapshot.items) {
   371→		if (
   372→			item.title.toLowerCase().includes(lowerQuery) ||
   373→			item.slugs.some((s) => s.includes(lowerQuery))
   374→		) {
   375→			results.push({
   376→				type: 'item',
   377→				ulid: item._ulid,
   378→				title: item.title,
   379→				matchedFields: ['title']
   380→			});
   381→		}
   382→	}
   383→
   384→	// Search inbox
   385→	for (const inbox of snapshot.inbox) {
   386→		if (inbox.text.toLowerCase().includes(lowerQuery)) {
   387→			results.push({
   388→				type: 'inbox',
   389→				ulid: inbox._ulid,
   390→				title: inbox.text.slice(0, 50),
   391→				matchedFields: ['text']
   392→			});
   393→		}
   394→	}
   395→
   396→	return {
   397→		results: results.slice(0, 20),
   398→		total: results.length,
   399→		showing: Math.min(results.length, 20)
   400→	};
   401→}
   402→
   403→/**
